{
  "references": [
    {
      "id": "R1",
      "summary_ko": "여성이 아무것도 자르고 있지 않은 것처럼 보임"
    },
    {
      "id": "R2",
      "summary_ko": "물체가 난데없이 나타남"
    },
    {
      "id": "R3",
      "summary_ko": "여성이 칼을 내려놓자 잠시 후 조리대 속으로 사라짐"
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "밝기 및 구조가 일시적으로 변했다가 돌아오는 패턴(깜빡임/순간 변형)"
    },
    {
      "id": "C2",
      "summary_ko": "여성이 돌아서면서 헤어스타일이 묶은 머리에서 짧은 픽시컷으로 변형됨"
    },
    {
      "id": "C3",
      "summary_ko": "여성이 조리대에서 돌아서 걸어갈 때 머리 모양, 스타일, 볼륨이 빠르게 변함"
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "자르는 동작의 허상에 관한 것과 밝기/구조의 일반적인 순간 변형은 대상과 현상이 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "자르는 행위 관련 설명과 여성의 머리카락 스타일 변화는 완전히 다른 현상입니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "칼질 동작 문제와 머리카락의 급격한 변형은 대상과 결함 내용이 일치하지 않습니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "객체 미식별 밝기/구조 변형 제안이 물체의 갑작스러운 등장 현상과 연관되었는지 정보가 부족하여 판단이 어렵습니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "물체가 허공에서 나타나는 현상과 머리카락 스타일 변화는 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "물체의 출현과 여성 헤어스타일 변형은 전혀 다른 현상입니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "칼이 사라지는 현상과 측정된 밝기/구조 순간 변형 제안의 관련 여부를 확정할 수 없습니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "칼이 조리대 속으로 사라지는 현상과 머리카락 스타일 변형은 대상이 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "칼의 소멸 현상과 머리카락 모양 및 볼륨의 급격한 변화는 무관합니다."
    }
  ]
}
